package udea.integrador.ingenote.application.service;
import udea.integrador.ingenote.application.exception.*; import udea.integrador.ingenote.application.port.in.ValoracionUseCase; import udea.integrador.ingenote.domain.model.*; import udea.integrador.ingenote.domain.port.out.*; import java.time.LocalDateTime; import java.util.*;
public class ValoracionService implements ValoracionUseCase { private final ValoracionPersistencePort votos; private final UsuarioPersistencePort usuarios; public ValoracionService(ValoracionPersistencePort v,UsuarioPersistencePort u){votos=v;usuarios=u;} private Usuario u(String c){return usuarios.buscarPorCorreo(c).orElseThrow(()->new AccesoDenegadoException("Usuario autenticado no encontrado"));} private void recurso(UUID r){if(!votos.existeRecurso(r))throw new RecursoNoEncontradoException("No existe el recurso");}
 public ResumenValoracion votar(String c,UUID r,short valor){if(valor!=1&&valor!=-1)throw new ReglaDeNegocioException("El voto debe ser 1 o -1");recurso(r);Usuario u=u(c);Optional<Valoracion> previo=votos.buscarPorRecursoYUsuario(r,u.id());if(previo.isPresent()&&previo.get().voto()==valor)votos.eliminar(previo.get().id());else votos.guardar(new Valoracion(previo.map(Valoracion::id).orElse(null),r,u.id(),valor,previo.map(Valoracion::fechaCreacion).orElse(LocalDateTime.now())));return resumen(c,r);} public ResumenValoracion retirar(String c,UUID r){recurso(r);Usuario u=u(c);votos.buscarPorRecursoYUsuario(r,u.id()).ifPresent(v->votos.eliminar(v.id()));return resumen(c,r);} public ResumenValoracion resumen(String c,UUID r){recurso(r);Usuario u=u(c);Short actual=votos.buscarPorRecursoYUsuario(r,u.id()).map(Valoracion::voto).orElse(null);return new ResumenValoracion(r,votos.puntajeNeto(r),votos.cantidadVotos(r),actual);}}
